# The 6 did not settle on its pad, so the remaining budget must first secure the untouched digits.
# Move both hands independently to close views of the 2 and 1 while preserving collision guards.
def move_pair(lxyz, lq, lg, rxyz, rq, rg, n=12):
    global obs, steps_left, halted, motion_fault
    if halted or motion_fault or steps_left <= 0:
        return False
    starts = [np.array(obs['state']['left_ee_pose']), np.array(obs['state']['right_ee_pose'])]
    targets = [np.array(list(lxyz)+list(lq)), np.array(list(rxyz)+list(rq))]
    for k in range(2):
        targets[k][3:] = targets[k][3:] / np.linalg.norm(targets[k][3:])
        if np.sum(starts[k][3:] * targets[k][3:]) < 0:
            targets[k][3:] = -targets[k][3:]
    for j in range(min(n, steps_left)):
        a = {'left_ee_joint_state':[lg], 'right_ee_joint_state':[rg]}
        commands = []
        for k in range(2):
            p = starts[k] + (targets[k]-starts[k])*min(1.0,(j+1)/max(1,n-3))
            p[3:] = p[3:]/np.linalg.norm(p[3:])
            commands.append(p)
            a[['left_ee_pose','right_ee_pose'][k]] = p
        obs, reward, terminated, truncated, info = step(a)
        steps_left -= 1
        halted = terminated or truncated or bool(info.get('success',False))
        for k in range(2):
            measured = np.array(obs['state'][['left_ee_pose','right_ee_pose'][k]])
            if np.linalg.norm(measured[:3]-commands[k][:3]) > 0.06 or 1-abs(float(np.sum(measured[3:]*commands[k][3:]))) > 0.03:
                motion_fault = True
        if halted or motion_fault:
            break
    errors = []
    for k in range(2):
        measured = np.array(obs['state'][['left_ee_pose','right_ee_pose'][k]])
        errors.append(float(np.linalg.norm(measured[:3]-targets[k][:3])))
        if errors[k] > 0.004 or 1-abs(float(np.sum(measured[3:]*targets[k][3:]))) > 0.001:
            motion_fault = True
    print('pair errors', errors, 'remaining', steps_left, 'fault', motion_fault, 'halted', halted)
    return not motion_fault
